def grav(grid):
    g=[r[:] for r in grid]; H,W=len(g),len(g[0])
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]]
    moved=True
    while moved:
        moved=False
        for r,c in sorted(pts,key=lambda p:(p[0],p[1])):
            nr,nc=r+1,c-1
            if 0<=nr<H and 0<=nc<W and not any(x==nr and y==nc for x,y in pts if True):
                pass
    return g
# simpler: repeat steps where each cell can move to (r+1,c-1) if empty
def grav2(g):
    Hh,Ww=len(g),len(g[0]); import copy
    cur=[r[:] for r in g]
    while True:
        nxt=[r[:] for r in cur]
        changed=False
        for r in range(Hh-1,-1,-1):
            for c in range(Ww):
                if cur[r][c]:
                    nr,nc=r+1,c-1
                    if 0<=nr<Hh and 0<=nc<Ww and cur[nr][nc]==0:
                        nxt[nr][nc]=cur[r][c]; nxt[r][c]=0; changed=True
        if not changed: break
        cur=nxt
    return cur
