def f(g):
    H=len(g); W=len(g[0])
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]]
    bottom=max(r for r,_ in pts)
    res=[[0]*W for _ in range(H)]
    for r,c in pts:
        nc=c+(r-bottom)
        if 0<=nc<W: res[r][nc]=g[r][c]
    return res
